<script setup lang="ts">
definePageMeta({ layout: "workspace" });
type OrderDetail = { orderNumber: string; title: string; description?: string; status: string; priority: string; scheduledDate?: string; assignedTo?: string; companyId?: { name?: string }; serviceId?: { name?: string }; lines: Array<{ _id?: string; title: string; quantity: number; status: string }> };
const route = useRoute();
const { t } = useLocale();
const { data: order, pending, error } = await useFetch<OrderDetail>(`/api/customer/orders/${route.params.id}`);
</script>
<template><section class="grid gap-4 pb-8"><NuxtLink to="/customer/orders" class="drixal-link-pill w-fit rounded-full px-4 py-2 text-sm font-bold">{{ t("common.orders") }}</NuxtLink><p v-if="error" class="drixal-danger rounded-xl p-4 font-semibold">{{ error.message }}</p><p v-else-if="pending" class="drixal-panel rounded-xl p-6 text-center drixal-muted">{{ t("common.loading") }}</p><template v-else-if="order"><div class="carbon-card rounded-xl p-5"><p class="text-xs font-black uppercase tracking-[0.18em] text-[var(--drixal-blue)]">{{ order.orderNumber }}</p><div class="mt-3 flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h1 class="text-2xl font-semibold">{{ order.title }}</h1><p class="drixal-muted mt-2 text-sm">{{ order.description }}</p></div><UBadge :label="t(`statuses.${order.status}`)" variant="soft" /></div></div><div class="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]"><div class="table-scroll"><table class="business-table"><thead><tr><th>{{ t("common.service") }}</th><th>{{ t("common.quantity") }}</th><th>{{ t("common.status") }}</th></tr></thead><tbody><tr v-for="line in order.lines" :key="line._id || line.title"><td class="font-bold">{{ line.title }}</td><td>{{ line.quantity }}</td><td><UBadge :label="t(`statuses.${line.status}`)" variant="soft" /></td></tr></tbody></table></div><aside class="drixal-panel h-fit rounded-xl p-5"><h2 class="text-lg font-semibold">{{ t("serviceOrders.summary") }}</h2><dl class="mt-4 grid gap-3 text-sm"><div><dt class="drixal-muted font-bold">{{ t("common.provider") }}</dt><dd class="mt-1">{{ order.companyId?.name || '-' }}</dd></div><div><dt class="drixal-muted font-bold">{{ t("common.service") }}</dt><dd class="mt-1">{{ order.serviceId?.name || '-' }}</dd></div><div><dt class="drixal-muted font-bold">{{ t("common.scheduledDate") }}</dt><dd class="mt-1">{{ order.scheduledDate ? new Date(order.scheduledDate).toLocaleDateString() : '-' }}</dd></div><div><dt class="drixal-muted font-bold">{{ t("common.assignedTo") }}</dt><dd class="mt-1">{{ order.assignedTo || '-' }}</dd></div></dl></aside></div></template></section></template>
